//! Managed shell environment: `env.sh`, `init.zsh`, `init.bash` rendered from the `shell` fields
//! of present tools, plus one marked block in `~/.zshrc` / `~/.bashrc` that sources them.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};

use crate::catalog::Catalog;
use crate::facts::Facts;
use crate::fs::{Backups, block};
use crate::state::{self, Paths};

const HEADER: &str =
    "# Generated by envira from the catalog; regenerate with `envira env`. Do not edit.\n";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rendered {
    pub env_sh: String,
    pub init_zsh: String,
    pub init_bash: String,
}

/// `~/x` -> `"$HOME/x"`; anything else double-quoted.
fn sh_path(p: &str) -> String {
    let esc = |s: &str| {
        s.replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('`', "\\`")
    };
    if p == "~" {
        "\"$HOME\"".into()
    } else if let Some(rest) = p.strip_prefix("~/") {
        format!("\"$HOME/{}\"", esc(rest))
    } else {
        format!("\"{}\"", esc(p))
    }
}

fn sq(s: &str) -> String {
    format!("'{}'", s.replace('\'', r"'\''"))
}

/// A path under the target home written with `$HOME`, as one shell word. A path with
/// characters the shell would expand inside double quotes (`$`, backquote, `"`, `\\`) gets its
/// literal part single-quoted: `"$HOME"/'odd $dir/env.sh'`.
fn home_rel(p: &Path, home: &Path) -> String {
    let plain = |s: &str| !s.contains(['$', '`', '"', '\\', '\n']);
    match p.strip_prefix(home) {
        Ok(rest) if plain(&rest.to_string_lossy()) => format!("\"$HOME/{}\"", rest.display()),
        Ok(rest) => format!("\"$HOME\"/{}", sq(&rest.to_string_lossy())),
        Err(_) if plain(&p.to_string_lossy()) => format!("\"{}\"", p.display()),
        Err(_) => sq(&p.to_string_lossy()),
    }
}

pub fn render(cat: &Catalog, facts: &Facts, paths: &Paths, present: &BTreeSet<String>) -> Rendered {
    let mut env = String::from(HEADER);
    // A directory already on PATH moves to the front, where detection puts it: a user copy
    // must win over a system one also on PATH (`$1` quoted in the patterns: taken literally).
    env.push_str(
        "envira_path_prepend() {\n  [ -d \"$1\" ] || return 0\n  envira_p=\":$PATH:\"\n  while case \"$envira_p\" in *\":$1:\"*) true ;; *) false ;; esac; do\n    envira_p=\"${envira_p%%:\"$1\":*}:${envira_p#*:\"$1\":}\"\n  done\n  envira_p=\"${envira_p#:}\"\n  envira_p=\"${envira_p%:}\"\n  PATH=\"$1${envira_p:+:$envira_p}\"\n  unset envira_p\n}\n",
    );
    let mut zsh = String::from(HEADER);
    let mut bash = String::from(HEADER);
    let env_file = home_rel(&paths.config_dir.join("env.sh"), &facts.home);
    for s in [&mut zsh, &mut bash] {
        s.push_str(&format!("[ -f {env_file} ] && . {env_file}\n"));
    }

    let mut ids: Vec<&String> = cat
        .tools
        .keys()
        .filter(|id| present.contains(*id))
        .collect();
    ids.sort_by_key(|id| (cat.category(id), *id));
    // PATH: `env.shell_path` and the dirs of present tools, in the order detection searches
    // them (`status::managed_dirs`).
    let rendered: Vec<&String> = cat
        .env
        .shell_path
        .iter()
        .chain(
            ids.iter()
                .filter_map(|id| cat.tools[*id].shell.as_ref())
                .flat_map(|s| &s.path),
        )
        .collect();
    let order: Vec<&str> = crate::status::managed_dirs(cat)
        .into_iter()
        .filter(|d| rendered.iter().any(|r| r.as_str() == *d))
        .collect();
    if !order.is_empty() {
        // Each one goes in front of the ones before it: last first.
        env.push_str("# PATH, from the last to the first\n");
        for d in order.iter().rev() {
            env.push_str(&format!("envira_path_prepend {}\n", sh_path(d)));
        }
    }
    for id in ids {
        let tool = &cat.tools[id];
        let Some(sh) = &tool.shell else { continue };
        let guard = format!("command -v {} >/dev/null 2>&1", tool.bin(id));
        if !sh.env.is_empty() {
            env.push_str(&format!("# {id}\n"));
            for (k, v) in &sh.env {
                // A path in the home (BUN_INSTALL=~/.bun) only when it is there: a tool found
                // elsewhere must not be pointed at envira's layout.
                if v.starts_with("~/") {
                    let p = sh_path(v);
                    env.push_str(&format!("[ -d {p} ] && export {k}={p}\n"));
                } else {
                    env.push_str(&format!("export {k}={}\n", sh_path(v)));
                }
            }
        }
        let aliases: Vec<String> = sh
            .alias
            .iter()
            .map(|(name, target)| {
                let first = target.split_whitespace().next().unwrap_or(target);
                format!(
                    "command -v {first} >/dev/null 2>&1 && alias {name}={}\n",
                    sq(target)
                )
            })
            .collect();
        for (shell, out) in [("zsh", &mut zsh), ("bash", &mut bash)] {
            let init = sh.init.get(shell);
            if aliases.is_empty() && init.is_none() {
                continue;
            }
            out.push_str(&format!("# {id}\n"));
            for a in &aliases {
                out.push_str(a);
            }
            if let Some(init) = init {
                out.push_str(&format!("if {guard}; then\n"));
                for l in init.lines() {
                    out.push_str(&format!("  {l}\n"));
                }
                out.push_str("fi\n");
            }
        }
    }
    env.push_str("export PATH\nunset -f envira_path_prepend\n");
    Rendered {
        env_sh: env,
        init_zsh: zsh,
        init_bash: bash,
    }
}

/// Lines for the rc file block of a shell.
pub fn rc_block(shell: &str, paths: &Paths, facts: &Facts) -> String {
    let f = home_rel(&paths.config_dir.join(format!("init.{shell}")), &facts.home);
    format!("[ -f {f} ] && . {f}")
}

pub fn rc_files(facts: &Facts) -> Vec<(&'static str, PathBuf)> {
    // macOS terminals start login shells, and a login bash reads ~/.bash_profile, not ~/.bashrc.
    let bash = if facts.os == "macos" {
        ".bash_profile"
    } else {
        ".bashrc"
    };
    [("zsh", ".zshrc"), ("bash", bash)]
        .into_iter()
        .map(|(s, f)| (s, facts.home.join(f)))
        .filter(|(s, f)| facts.has_shell(s) || f.exists())
        .collect()
}

/// Writes the generated files and ensures the rc blocks; returns the files that changed.
pub fn install(
    cat: &Catalog,
    facts: &Facts,
    paths: &Paths,
    present: &BTreeSet<String>,
) -> Result<Vec<PathBuf>> {
    let r = render(cat, facts, paths, present);
    let mut changed = Vec::new();
    for (name, text) in [
        ("env.sh", &r.env_sh),
        ("init.zsh", &r.init_zsh),
        ("init.bash", &r.init_bash),
    ] {
        // Like any edit of the user's files: through a link the user keeps there (a dotfiles
        // repo), under the rule for links when root writes it.
        let f = crate::fs::edit_target(&paths.config_dir.join(name), true)?;
        if std::fs::read_to_string(&f).ok().as_deref() != Some(text.as_str()) {
            // Like an edit too: an existing file keeps its owner; a new one (and the directories
            // made for it) belongs to the user under `sudo envira`.
            if let Some(dir) = f.parent() {
                state::create_dir_all_owned(dir, facts)?;
            }
            crate::files::replace(&f, text.as_bytes(), None)
                .with_context(|| format!("writing {}", f.display()))?;
            changed.push(f);
        }
    }
    let backups = Backups::new(paths.state_dir.join("backups"));
    for (shell, rc) in rc_files(facts) {
        let content = rc_block(shell, paths, facts);
        if !block(&backups, &rc, "envira", "#", Some(&content), true)? {
            // Ownership as for any edit: kept, or the directory's owner for a new rc.
            block(&backups, &rc, "envira", "#", Some(&content), false)?;
            changed.push(rc);
        }
    }
    Ok(changed)
}

/// Lines in rc files, outside envira's block, that duplicate what envira renders (for `doctor`).
pub fn rc_duplicates(cat: &Catalog, facts: &Facts, present: &BTreeSet<String>) -> Vec<String> {
    let mut needles: Vec<String> = Vec::new();
    for (id, t) in &cat.tools {
        if !present.contains(id) {
            continue;
        }
        let Some(sh) = &t.shell else { continue };
        needles.extend(sh.alias.keys().map(|a| format!("alias {a}=")));
        needles.extend(sh.env.keys().map(|k| format!("export {k}=")));
        needles.extend(
            sh.path
                .iter()
                .filter_map(|p| p.strip_prefix("~/"))
                .map(|p| p.to_string()),
        );
        if sh.init.values().any(|i| i.contains("fnm env")) {
            needles.push("fnm env".into());
        }
    }
    let mut out = Vec::new();
    for (_, rc) in rc_files(facts) {
        let Ok(text) = std::fs::read_to_string(&rc) else {
            continue;
        };
        let mut inside = false;
        for (n, line) in text.lines().enumerate() {
            let t = line.trim();
            if t == "# >>> envira >>>" {
                inside = true;
            } else if t == "# <<< envira <<<" {
                inside = false;
            } else if !inside
                && !t.starts_with('#')
                && needles.iter().any(|nd| t.contains(nd.as_str()))
            {
                out.push(format!(
                    "~/{}:{}: {t}",
                    rc.file_name().unwrap_or_default().to_string_lossy(),
                    n + 1
                ));
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn odd_paths_stay_one_literal_word() {
        let home = Path::new("/home/user");
        assert_eq!(
            home_rel(Path::new("/home/user/.config/envira/env.sh"), home),
            "\"$HOME/.config/envira/env.sh\""
        );
        assert_eq!(
            home_rel(Path::new("/home/user/my dir/env.sh"), home),
            "\"$HOME/my dir/env.sh\""
        );
        assert_eq!(
            home_rel(Path::new("/home/user/$x/`id`/it's/env.sh"), home),
            "\"$HOME\"/'$x/`id`/it'\\''s/env.sh'"
        );
        assert_eq!(
            home_rel(Path::new("/opt/$v/env.sh"), home),
            "'/opt/$v/env.sh'"
        );
        // What the shell makes of it.
        let word = home_rel(Path::new("/home/user/$x/`id`/it's \"q\"/env.sh"), home);
        let out = std::process::Command::new("sh")
            .args(["-c", &format!("HOME=/home/user; printf %s {word}")])
            .output()
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(&out.stdout),
            "/home/user/$x/`id`/it's \"q\"/env.sh"
        );
    }
    use crate::catalog::load::{embedded_layer, load};

    fn setup() -> (tempfile::TempDir, Catalog, Facts, Paths) {
        let d = tempfile::tempdir().unwrap();
        let facts = Facts::sample(d.path());
        let paths = Paths {
            state_dir: d.path().join(".local/state/envira"),
            config_dir: d.path().join(".config/envira"),
            cache_dir: d.path().join(".cache/envira"),
        };
        (d, load(&[embedded_layer()]).unwrap().catalog, facts, paths)
    }

    /// The generated env.sh, sourced by sh, bash and zsh: a managed dir already on PATH moves
    /// to the front (all its copies go), absent dirs are left out, and GOROOT is never set (go
    /// finds it from where its binary is).
    #[test]
    fn env_sh_moves_managed_dirs_to_the_front() {
        let (d, cat, facts, paths) = setup();
        let present: BTreeSet<String> = ["go"].iter().map(|s| s.to_string()).collect();
        let r = render(&cat, &facts, &paths, &present);
        let env = d.path().join("env.sh");
        std::fs::write(&env, &r.env_sh).unwrap();
        std::fs::create_dir_all(d.path().join("go/bin")).unwrap();
        let home = d.path().display().to_string();
        for sh in ["sh", "bash", "zsh"] {
            if std::process::Command::new("sh")
                .args(["-c", &format!("command -v {sh}")])
                .output()
                .map_or(true, |o| !o.status.success())
            {
                continue;
            }
            let out = std::process::Command::new(sh)
                .args([
                    "-c",
                    &format!(
                        ". {} && printf '%s|%s' \"$PATH\" \"${{GOROOT-unset}}\"",
                        env.display()
                    ),
                ])
                .env("HOME", &home)
                .env_remove("GOROOT")
                .env_remove("ENV")
                .env("PATH", format!("/usr/bin:{home}/go/bin:/bin:{home}/go/bin"))
                .output()
                .unwrap();
            let out = String::from_utf8_lossy(&out.stdout).to_string();
            assert_eq!(out, format!("{home}/go/bin:/usr/bin:/bin|unset"), "{sh}");
        }
    }

    /// A shell searches the managed dirs in the order detection does: the copy of a command
    /// that status reports is the one the shell runs.
    #[test]
    fn env_sh_orders_path_as_detection_does() {
        let (d, cat, facts, paths) = setup();
        let present: BTreeSet<String> = cat.tools.keys().cloned().collect();
        let r = render(&cat, &facts, &paths, &present);
        // Rendered: `env.shell_path` and the tools' dirs (`env.path` is detection's alone).
        let rendered: Vec<&String> = cat
            .tools
            .values()
            .filter_map(|t| t.shell.as_ref())
            .flat_map(|s| &s.path)
            .chain(&cat.env.shell_path)
            .collect();
        let expected: Vec<String> = crate::status::managed_dirs(&cat)
            .into_iter()
            .filter(|p| rendered.iter().any(|r| r.as_str() == *p))
            .map(|p| facts.expand_home(p))
            .filter(|p| p.starts_with(&d.path().display().to_string()))
            .collect();
        assert!(expected.len() > 5, "{expected:?}");
        for p in &expected {
            std::fs::create_dir_all(p).unwrap();
        }
        let env = d.path().join("env.sh");
        std::fs::write(&env, &r.env_sh).unwrap();
        let out = std::process::Command::new("sh")
            .args(["-c", &format!(". '{}' && echo \"$PATH\"", env.display())])
            .env("HOME", d.path())
            .env("PATH", "/usr/bin:/bin")
            .output()
            .unwrap();
        let path = String::from_utf8_lossy(&out.stdout).trim().to_string();
        let got: Vec<&str> = path
            .split(':')
            .filter(|p| p.starts_with(&d.path().display().to_string()))
            .collect();
        assert_eq!(got, expected);
    }

    #[test]
    fn renders_only_present_tools_with_guards() {
        let (_d, cat, facts, paths) = setup();
        let present: BTreeSet<String> = ["bun", "fnm", "lsd"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let r = render(&cat, &facts, &paths, &present);
        assert!(
            r.env_sh.contains(
                "# PATH, from the last to the first\nenvira_path_prepend \"$HOME/.bun/bin\"\nenvira_path_prepend \"$HOME/.local/share/fnm\"\nenvira_path_prepend \"$HOME/.local/bin\"\n"
            ),
            "{}",
            r.env_sh
        );
        assert!(
            r.env_sh
                .contains("# bun\n[ -d \"$HOME/.bun\" ] && export BUN_INSTALL=\"$HOME/.bun\"\n"),
            "{}",
            r.env_sh
        );
        assert!(
            !r.env_sh.contains(".cargo/bin"),
            "rust-toolchain is not present"
        );
        assert!(
            r.env_sh
                .ends_with("export PATH\nunset -f envira_path_prepend\n")
        );
        assert!(r.init_zsh.contains(
            "[ -f \"$HOME/.config/envira/env.sh\" ] && . \"$HOME/.config/envira/env.sh\"\n"
        ));
        assert!(
            r.init_zsh
                .contains("command -v lsd >/dev/null 2>&1 && alias ls='lsd'\n")
        );
        assert!(r.init_zsh.contains("if command -v fnm >/dev/null 2>&1; then\n  eval \"$(fnm env --shell zsh)\"\n  eval \"$(fnm completions --shell zsh)\"\nfi\n"));
        assert!(r.init_bash.contains("--shell bash"));
        assert!(!r.init_bash.contains("_bun"), "bun has zsh-only init");
    }

    #[test]
    fn rendered_env_is_valid_sh_and_does_not_duplicate_path() {
        let (d, cat, facts, paths) = setup();
        std::fs::create_dir_all(d.path().join(".bun/bin")).unwrap();
        let present: BTreeSet<String> = ["bun".to_string()].into();
        install(&cat, &facts, &paths, &present).unwrap();
        let env = paths.config_dir.join("env.sh");
        let out = std::process::Command::new("sh")
            .arg("-c")
            .arg(format!(". '{0}'; . '{0}'; echo \"$PATH\"", env.display()))
            .env("HOME", d.path())
            .env("PATH", "/usr/bin:/bin")
            .output()
            .unwrap();
        let path = String::from_utf8(out.stdout).unwrap();
        assert_eq!(
            path.trim(),
            format!("{}/.bun/bin:/usr/bin:/bin", d.path().display())
        );
    }

    #[test]
    fn macos_bash_uses_the_login_profile() {
        let (d, _cat, mut facts, _paths) = setup();
        let names = |f: &Facts| {
            rc_files(f)
                .into_iter()
                .map(|(s, p)| (s, p.strip_prefix(d.path()).unwrap().display().to_string()))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            names(&facts),
            [
                ("zsh", ".zshrc".to_string()),
                ("bash", ".bashrc".to_string())
            ]
        );
        facts.os = "macos".into();
        assert_eq!(
            names(&facts),
            [
                ("zsh", ".zshrc".to_string()),
                ("bash", ".bash_profile".to_string())
            ]
        );
    }

    /// env.sh kept in a dotfiles repo and linked into place stays linked; the repo's file is
    /// what changes.
    #[test]
    fn a_linked_generated_file_stays_linked() {
        let (d, cat, facts, paths) = setup();
        let repo = d.path().join("dotfiles/env.sh");
        std::fs::create_dir_all(repo.parent().unwrap()).unwrap();
        std::fs::write(&repo, "# old\n").unwrap();
        std::fs::create_dir_all(&paths.config_dir).unwrap();
        let env = paths.config_dir.join("env.sh");
        std::os::unix::fs::symlink(&repo, &env).unwrap();
        let present: BTreeSet<String> = ["lsd".to_string()].into();
        install(&cat, &facts, &paths, &present).unwrap();
        assert!(
            std::fs::symlink_metadata(&env)
                .unwrap()
                .file_type()
                .is_symlink()
        );
        assert_ne!(std::fs::read_to_string(&repo).unwrap(), "# old\n");
    }

    #[test]
    fn install_is_idempotent_and_adds_one_rc_block() {
        let (d, cat, facts, paths) = setup();
        std::fs::write(d.path().join(".zshrc"), "alias ls=lsd\n").unwrap();
        let present: BTreeSet<String> = ["lsd".to_string()].into();
        let first = install(&cat, &facts, &paths, &present).unwrap();
        assert_eq!(first.len(), 5, "{first:?}");
        let second = install(&cat, &facts, &paths, &present).unwrap();
        assert!(second.is_empty(), "{second:?}");
        let zshrc = std::fs::read_to_string(d.path().join(".zshrc")).unwrap();
        assert_eq!(zshrc.matches("# >>> envira >>>").count(), 1);
        assert!(zshrc.contains(
            "[ -f \"$HOME/.config/envira/init.zsh\" ] && . \"$HOME/.config/envira/init.zsh\""
        ));
        assert_eq!(
            rc_duplicates(&cat, &facts, &present),
            vec!["~/.zshrc:1: alias ls=lsd"]
        );
    }
}
